-- Big Order By 测试用例
-- 创建4个表，每表20个int字段
CREATE TABLE t0(c0 int, c1 int, c2 int, c3 int, c4 int, c5 int, c6 int, c7 int, c8 int, c9 int, c10 int, c11 int, c12 int, c13 int, c14 int, c15 int, c16 int, c17 int, c18 int, c19 int);
CREATE TABLE t1(c0 int, c1 int, c2 int, c3 int, c4 int, c5 int, c6 int, c7 int, c8 int, c9 int, c10 int, c11 int, c12 int, c13 int, c14 int, c15 int, c16 int, c17 int, c18 int, c19 int);
CREATE TABLE t2(c0 int, c1 int, c2 int, c3 int, c4 int, c5 int, c6 int, c7 int, c8 int, c9 int, c10 int, c11 int, c12 int, c13 int, c14 int, c15 int, c16 int, c17 int, c18 int, c19 int);
CREATE TABLE t3(c0 int, c1 int, c2 int, c3 int, c4 int, c5 int, c6 int, c7 int, c8 int, c9 int, c10 int, c11 int, c12 int, c13 int, c14 int, c15 int, c16 int, c17 int, c18 int, c19 int);
SELECT * FROM t0, t1, t2, t3 ORDER BY t0.c0, t1.c5, t2.c10, t3.c15;
SELECT * FROM t0, t1, t2, t3 ORDER BY t3.c19 DESC, t0.c0 ASC, t1.c10 DESC;
SELECT * FROM t0, t1, t2, t3 ORDER BY t0.c5, t1.c5, t2.c5, t3.c5, t0.c10;
DROP TABLE t0;
DROP TABLE t1;
DROP TABLE t2;
DROP TABLE t3;